head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst15400";
scwin.addSearchTop = null;
scwin.addSearch = null;
scwin.title_of_account1 = null;
scwin.title_of_account2 = null;
scwin.finstat = undefined;
scwin.finrate = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("nowYear")) { pc.set("nowYear", $c.date.getServerDateTime("yyyy")); }
};

// 연도 선택 항목 — as-is 가 서버에서 그리던 범위를 화면에서 세운다(값 원천 = dma_pageContext.nowYear).

/**
 * @method
 * @name init_yearItems
 * @description 초기화 — year Items
 * @returns {void}
 * @hidden N
 */
scwin.init_yearItems = function () {
    const pc = $c.util.getComponent("dma_pageContext");
    const ny = Number(pc && pc.get ? pc.get("nowYear") : 0);
    if (!ny) { /* TODO Stage2: [sdd] 연도 선택 — nowYear 미충전(init_nowVars 앞에서 불렸다) */ return 0; }
    {
        const s = $c.util.getComponent("slc_fiscalyear");
        if (!s || typeof s.addItem !== "function") { /* TODO Stage2: [sdd] 연도 선택 대상 부재:  "slc_fiscalyear */ }
        else {
            if (typeof s.removeAll === "function") { s.removeAll(); }
            for (let i = 0; i <= (ny - 1996); i++) {
                const y = String(ny - (i - (0)) * 1);
                s.addItem(y, y);
            }
            s.setValue(String((ny - 1)));
        }
    }
    return 1;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    scwin.title_of_account2.setStyle("display", "none");
    await scwin.fnOrder('A080', 'D');
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        scwin.addSearchTop.setStyle("display", "none");
        scwin.addSearch.setStyle("display", "none");
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst15400.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.finstat =["A010","A040","A080","A090","A100","A110","A120","A130","A140","A160","A170","A180","A190","A200"]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst15400' }); }

try { scwin.finrate =["B010","B020","B030","B040","B050","B060","B080","B090"]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jlddst15400' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.addSearchTop = $c.util.getComponent('addSearchTop');
        scwin.addSearch = $c.util.getComponent('addSearch');
        scwin.title_of_account1 = $c.util.getComponent('title_of_account1');
        scwin.title_of_account2 = $c.util.getComponent('title_of_account2');
        scwin.init_nowVars();
        scwin.init_yearItems();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst15400.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_fnSearchCorpBasicInfo_onclick
 * @description btn_fnSearchCorpBasicInfo 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchCorpBasicInfo_onclick = async function(e){
    try {
        await scwin.fnSearchCorpBasicInfo();return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst15400.btn_fnSearchCorpBasicInfo_onclick' }); }
};

/**
 * @method
 * @name btn_fnFindCompanySelect_onclick
 * @description btn_fnFindCompanySelect 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnFindCompanySelect_onclick = function(e){
    try {
        scwin.fnFindCompanySelect(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15400.btn_fnFindCompanySelect_onclick' }); }
};

/**
 * @method
 * @name btn_changeTitleOfAccountPanel_onclick
 * @description btn_changeTitleOfAccountPanel 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_changeTitleOfAccountPanel_onclick = function(e){
    try {
        scwin.changeTitleOfAccountPanel(); return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15400.btn_changeTitleOfAccountPanel_onclick' }); }
};

/**
 * @method
 * @name ipt_chAll1_onclick
 * @description ipt_chAll1 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chAll1_onclick = function(e){
    try {
        scwin.changeAllCheckState()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15400.ipt_chAll1_onclick' }); }
};

/**
 * @method
 * @name ipt_chAll2_onclick
 * @description ipt_chAll2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_chAll2_onclick = function(e){
    try {
        scwin.changeAllCheckState()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst15400.ipt_chAll2_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearch_onclick
 * @description btn_fnSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearch_onclick = async function(e){
    try {
        await scwin.fnSearch(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst15400.btn_fnSearch_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst15400.btn_fnDownload_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/compfinance/financialinfo.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/compfinance/financialinfo.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    await scwin.fnSearchCorpBasicInfo();
};

/**
 * @method
 * @name fnOrder
 * @description fn Order 처리
 * @param {*} mode mode
 * @param {*} stat stat
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOrder = async function (mode, stat) {
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $("#searchForm > #pageIndex").val("1");
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    const titleofaccnt = scwin.makeTitleOfAccountParamString();
    $c.util.getComponent('ipt_titleofaccnt').setValue(titleofaccnt);
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchFinancialInfoOfSomeCorps");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "list");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack1
 * @description fn Search Call Back1 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack1 = function (data) {
    $("#mainContents").empty().append(data);
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnLegendTooltip( " ') */
};

/**
 * @method
 * @name changeTitleOfAccountPanel
 * @description change Title Of Account Panel 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeTitleOfAccountPanel = function () {
    let val = $c.util.getComponent('slc_fininfotype').getValue(); if (val == null) { val = ''; }
    if (val === "finstat") {
        scwin.title_of_account1.setStyle("display", "");
        scwin.title_of_account2.setStyle("display", "none");
        $c.util.getComponent('ipt_finsearchtype').setValue("finstat");
        $c.util.getComponent("dma_fnDownloadReq").set("orderMode", scwin.finstat[0]);
        $c.util.getComponent("dma_fnDownloadReq").set("orderStat", 'D');
    } else {
        if (val === "finrate") {
            scwin.title_of_account1.setStyle("display", "none");
            scwin.title_of_account2.setStyle("display", "");
            $c.util.getComponent('ipt_finsearchtype').setValue("finrate");
            $c.util.getComponent("dma_fnDownloadReq").set("orderMode", scwin.finrate[0]);
            $c.util.getComponent("dma_fnDownloadReq").set("orderStat", 'D');
        }
    }
};

/**
 * @method
 * @name makeTitleOfAccountParamString
 * @description make Title Of Account Param String 처리
 * @returns {void}
 * @hidden N
 */
scwin.makeTitleOfAccountParamString = function () {
    let paramString = "";
    let flag = false;
    paramString = "";
    const finsearchtype = $c.util.getComponent('ipt_finsearchtype').getValue();
    if (finsearchtype === "finstat") {
        for (let i = 0; i < scwin.finstat.length; i++) {
            flag = scwin.checkChkBoxStatus(scwin.finstat[i]);
            if (flag) {
                paramString += scwin.finstat[i];
                if (i !== (scwin.finstat.length - 1)) {
                    paramString += "|";
                }
            }
        }
    } else {
        if (finsearchtype === "finrate") {
            for (let i = 0; i < scwin.finrate.length; i++) {
                flag = scwin.checkChkBoxStatus(scwin.finrate[i]);
                if (flag) {
                    paramString += scwin.finrate[i];
                    if (i !== (scwin.finrate.length - 1)) {
                        paramString += "|";
                    }
                }
            }
        }
    }
    return paramString;
};

/**
 * @method
 * @name checkChkBoxStatus
 * @description check Chk Box Status 처리
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.checkChkBoxStatus = function (id) {
    return $("#" + id).is(":checked");
};

/**
 * @method
 * @name changeAllCheckState
 * @description change All Check State 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeAllCheckState = function () {
    let val = $c.util.getComponent('slc_fininfotype').getValue(); if (val == null) { val = ''; }
    if (val === "finstat") {
        for (let i = 0; i < scwin.finstat.length; i++) {
            if ($("#ipt_chAll1").is(":checked")) {
                $("#" + scwin.finstat[i]).attr("checked", true);
            } else {
                $("#" + scwin.finstat[i]).attr("checked", false);
            }
        }
    } else {
        if (val === "finrate") {
            for (let i = 0; i < scwin.finrate.length; i++) {
                if ($("#ipt_chAll2").is(":checked")) {
                    $("#" + scwin.finrate[i]).attr("checked", true);
                } else {
                    $("#" + scwin.finrate[i]).attr("checked", false);
                }
            }
        }
    }
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    const titleofaccnt = scwin.makeTitleOfAccountParamString();
    $c.util.getComponent('ipt_titleofaccnt').setValue(titleofaccnt);
    $c.util.getComponent("dma_fnDownloadReq").set("method", "download_corps");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "download_corps");
    await scwin.tx_fnDownload();
};

/**
 * @method
 * @name fnFindCompanySelect
 * @description fn Find Company Select 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnFindCompanySelect = function () {
    const wUrl = "/compfinance/financialinfo.do?method=searchFinancialInfoOfCorpSelect";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(wUrl), { id: "회사선택", width: "725", height: "600", scrollbars: true, resizable: false, type: "pageFramePopup" }, {});
};

/**
 * @method
 * @name fnSearchCorpBasicInfo
 * @description fn Search Corp Basic Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpBasicInfo = async function () {
    let val = $c.util.getComponent('AKCKwd').getValue(); if (val == null) { val = ''; }
    if (val !== "") {
        $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", val);
        /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnAKCKwdSearchCorpName( " ') */
    } else {
        await $c.win.alert("조회할 회사명을 입력해 주세요.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
    }
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    if (items.length === 1) {
        await scwin.fnSearchCorpCode(items[0]);
    } else {
        if (items.length > 1) {
            scwin.fnFindCompanySelect();
        } else {
            await scwin.fnSearchCorpCode(null);
        }
    }
};

/**
 * @method
 * @name fnSearchCorpCode
 * @description fn Search Corp Code 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpCode = async function (items) {
    if (items == null) {
        const val = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
    } else {
        const comabbr = items.comabbrv;
        const isurcd = items.isurcd;
        const repisusrtcd2 = items.repisusrtcd2;
        const spotisutrdmkttpcd = items.spotisutrdmkttpcd;
        const liststatcd = items.liststatcd;
        let mkttpimg = "";
        if (spotisutrdmkttpcd === "1") {
            mkttpimg = "<img src='../images/common/icn_t_yu.gif' class='vmiddle' alt='유가증권' />&nbsp;";
        } else {
            if (spotisutrdmkttpcd === "2") {
                mkttpimg = "<img src='../images/common/icn_t_ko.gif' class='vmiddle' alt='코스닥' />&nbsp;";
            } else {
                if (spotisutrdmkttpcd === "6") {
                    mkttpimg = "<img src='../images/common/icn_t_konex.gif' class='vmiddle' alt='코넥스' />&nbsp;";
                }
            }
        }
        let liststatimg = "";
        if (liststatcd === 'D') {
            liststatimg = "<img src='../images/common/icn_t_pe.gif' class='vmiddle' alt='폐' />";
        }
        const vTr = $("<tr />");
        vTr.attr("style", "cursor: pointer;");
        const vTd = $("<td />");
        vTd.addClass("first txc");
        const vInput1 = $("<input type='hidden' id='arrIsurCd' name='arrIsurCd' />");
        vInput1.val(isurcd);
        const vInput2 = $("<input type='hidden' id='stkCd' />");
        vInput2.val(repisusrtcd2 + "|" + comabbr);
        vTd.append(vInput1);
        vTd.append(vInput2);
        const vSpan = $("<span />");
        vSpan.addClass("dvs");
        vSpan.html(repisusrtcd2);
        vTd.append(vSpan);
        const vTd2 = $("<td />");
        vTd2.attr("id", "sub");
        vTd2.append(mkttpimg + "" + comabbr + "&nbsp;" + liststatimg);
        vTr.append(vTd);
        vTr.append(vTd2);
        let vChk = false;
        $('#txt_addStockHtml').find('input:hidden[name=arrIsurCd]').each(function() {
                if ($(this).val() === isurcd) {
                    vChk = true;
                }
        });
        if (vChk) {
            await $c.win.alert('동일한 회사명이 있습니다.');
        } else {
            if ($('#txt_addStockHtml').find('tr').length < 10) {
                $('#txt_addStockHtml').append(vTr);
                scwin.fnAddStock($c.util.getComponent('txt_addStockHtml').getValue());
            } else {
                await $c.win.alert('회사명을 최대 10개이므로 추가할 수 없습니다.');
            }
        }
    }
    $c.util.getComponent('AKCKwd').setValue('');
    $c.util.getComponent("AKCKwd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
};

/**
 * @method
 * @name fnAddStock
 * @description fn Add Stock 처리
 * @param {*} html html
 * @returns {void}
 * @hidden N
 */
scwin.fnAddStock = function (html) {
    if ($.trim(html) !== "") {
        let spanHtml = "";
        (($c.util.getComponent('txt_addStockHtml')) && ($c.util.getComponent('txt_addStockHtml')).setValue ? ($c.util.getComponent('txt_addStockHtml')).setValue(html) : (($c.util.getComponent('txt_addStockHtml')) && ($c.util.getComponent('txt_addStockHtml')).setText ? ($c.util.getComponent('txt_addStockHtml')).setText(html) : void (html)));
        $('#txt_addStockHtml').find('td[id=sub]').each(function() {
                spanHtml += '<li>' + $(this).html() + '</li>';
        });
        $('#addSearch').find('ul').html(spanHtml);
        scwin.addSearch.setStyle("display", "");
        scwin.addSearchTop.setStyle("display", "");
    } else {
        $c.util.getComponent('txt_addStockHtml').setLabel("");
        /* TODO Stage2: [sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_label — {target}.setLabel({args}) */
        scwin.addSearch.setStyle("display", "none");
        scwin.addSearchTop.setStyle("display", "none");
    }
};

/**
 * @method
 * @name fnGetAddStock
 * @description fn Get Add Stock 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnGetAddStock = function () {
    return $c.util.getComponent('txt_addStockHtml').getValue();
};
